impl crate::Payload for Payload {
    const TYPE_URI: &'static str = "https://trusttasks.org/spec/vta/witness/accept/0.1";
    const IS_PROOF_REQUIRED: bool = true;
    const IS_ISSUED_AT_REQUIRED: bool = true;
    const IS_RECIPIENT_REQUIRED: bool = true;
    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\n  \"$defs\": {\n    \"CarriedDocument\": {\n      \"description\": \"A whole Trust Task document — `id`, `type`, `payload` and every other member, `proof` included — carried between the VTA and the witness by the client: one the VTA built and signed for the client to send, or one the witness returned for the client to hand back. Typed as an open object so every member survives a round trip: carried exactly as built or received, never re-serialised, because its proof is over itself. Its envelope is checked by the VTA against the session record (CONVENTIONS.md §3), not by this schema.\",\n      \"minProperties\": 1,\n      \"title\": \"CarriedDocument\",\n      \"type\": \"object\"\n    },\n    \"DigestMultibase\": {\n      \"description\": \"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\\"interoperability is not guaranteed between implementations using such values\\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.\",\n      \"examples\": [\n        \"zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR\"\n      ],\n      \"minLength\": 16,\n      \"pattern\": \"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)$\",\n      \"title\": \"DigestMultibase\",\n      \"type\": \"string\"\n    },\n    \"Evidence\": {\n      \"additionalProperties\": false,\n      \"description\": \"The two documents a holder ships with the VWC so a verifier can pair it with the session that produced it (witness/session/submit, This response is the outcome evidence). Each is carried exactly as sent or received, never re-serialised.\",\n      \"properties\": {\n        \"outcome\": {\n          \"$ref\": \"#/$defs/CarriedDocument\",\n          \"description\": \"The witness/session/submit #response, as handed back, under the witness's proof. It carries the VWC and its vwcDigestMultibase.\"\n        },\n        \"session\": {\n          \"$ref\": \"#/$defs/CarriedDocument\",\n          \"description\": \"The witness/session document that opened the session, as the VTA built it. The VWC's taskContext is its id and its taskDigestMultibase is computed over it.\"\n        }\n      },\n      \"required\": [\n        \"session\",\n        \"outcome\"\n      ],\n      \"title\": \"Evidence\",\n      \"type\": \"object\"\n    },\n    \"Ext\": {\n      \"additionalProperties\": true,\n      \"description\": \"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\n      \"minProperties\": 1,\n      \"propertyNames\": {\n        \"pattern\": \"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"\n      },\n      \"title\": \"Ext\",\n      \"type\": \"object\"\n    },\n    \"Response\": {\n      \"$anchor\": \"response\",\n      \"additionalProperties\": false,\n      \"description\": \"The stored VWC's vault handle, its digest, and the evidence documents that carry it. Sent only once the VWC is verified and stored.\",\n      \"properties\": {\n        \"credentialId\": {\n          \"description\": \"The credential-vault handle the VWC is now stored under, with its evidence.\",\n          \"maxLength\": 256,\n          \"minLength\": 1,\n          \"type\": \"string\"\n        },\n        \"evidence\": {\n          \"$ref\": \"#/$defs/Evidence\"\n        },\n        \"ext\": {\n          \"$ref\": \"#/$defs/Ext\"\n        },\n        \"sessionId\": {\n          \"$ref\": \"#/$defs/SessionId\"\n        },\n        \"vwcDigestMultibase\": {\n          \"$ref\": \"#/$defs/DigestMultibase\",\n          \"description\": \"The digest the witness returned for the VWC, which the VTA has checked against the VWC it stored: over the RFC 8785 canonicalization of the VWC, proof included.\"\n        },\n        \"witness\": {\n          \"description\": \"The witness that issued the VWC: the session's witness, since a VWC issued by any other party is refused, not stored.\",\n          \"pattern\": \"^did:\",\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"sessionId\",\n        \"credentialId\",\n        \"witness\",\n        \"vwcDigestMultibase\",\n        \"evidence\"\n      ],\n      \"title\": \"VTA Witness — Accept — response payload\",\n      \"type\": \"object\"\n    },\n    \"SessionId\": {\n      \"description\": \"The id of the witness/session document the VTA built in vta/witness/open: the session's name, the thread every document of the session is on, and the value the VWC carries as taskContext. The VTA keys its state for the session by it.\",\n      \"maxLength\": 256,\n      \"minLength\": 1,\n      \"title\": \"SessionId\",\n      \"type\": \"string\"\n    }\n  },\n  \"$id\": \"https://trusttasks.org/spec/vta/witness/accept/0.1\",\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"additionalProperties\": false,\n  \"description\": \"A client hands its VTA the witness's answer to the submission; the VTA verifies the Verifiable Witness Credential it carries against the session, and stores it in the credential vault with its evidence.\",\n  \"properties\": {\n    \"ext\": {\n      \"$ref\": \"#/$defs/Ext\"\n    },\n    \"response\": {\n      \"$ref\": \"#/$defs/CarriedDocument\",\n      \"description\": \"The witness/session/submit/0.1 #response the witness returned, exactly as received, under the witness's proof. It carries the VWC and its vwcDigestMultibase.\"\n    },\n    \"sessionId\": {\n      \"$ref\": \"#/$defs/SessionId\"\n    }\n  },\n  \"required\": [\n    \"sessionId\",\n    \"response\"\n  ],\n  \"title\": \"VTA Witness — Accept — payload\",\n  \"type\": \"object\"\n}\n",
    );
}
