/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::SESSION_UNKNOWN,
    error_codes::RESPONSE_INVALID,
    error_codes::VWC_INVALID,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vta/witness/accept:sessionUnknown`
    ///
    /// No session record with this id in state `presented`, in a context the caller may act in — including one that expired, or was accepted with a different outcome.
    ///
    /// Declared `retryable: false`.
    pub const SESSION_UNKNOWN: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/witness/accept:sessionUnknown",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/witness/accept:responseInvalid`
    ///
    /// The document handed back is not the witness's witness/session/submit/0.1 #response for this session: wrong type, issuer, recipient or thread, or a proof that does not verify for the witness's DID.
    ///
    /// Declared `retryable: false`.
    pub const RESPONSE_INVALID: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/witness/accept:responseInvalid",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/witness/accept:vwcInvalid`
    ///
    /// The response is the witness's, but the VWC does not verify against the session: not issued by the witness, a failing proof, a taskContext or task digest naming another session document, a subject or object digest naming another party or credential, or a vwcDigestMultibase that does not match. Nothing is stored.
    ///
    /// Declared `retryable: false`.
    pub const VWC_INVALID: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/witness/accept:vwcInvalid",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
